(* [comment removed for export] *)
Lemma rg3_L_W : forall (n : nat) C Ar A md (s : Z) (S : TSet) (f : frw) (fl : word)
    (datad nd datas ns psl pdl swpl dwpl dh x2 : Z) (f3 : bool) (r0 : bvmap 5 word) m0 m r (i : Z),
  rg_ok C Ar A md s datad nd datas ns ->
  (1 <= dh < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z -> (x2 = if f3 then 0 else 4)%Z ->
  (forall i', 0 <= i' < dh -> datad <= pdl + 4 * dwpl * i' /\ pdl + 4 * dwpl * i' + 4 <= datad + nd)%Z ->
  (forall i', 0 <= i' < dh -> datas <= psl + 4 * swpl * i' /\ psl + 4 * swpl * i' + 4 + x2 <= datas + ns)%Z ->
  (Z.of_nat n = dh - 1 - i)%Z -> (0 <= i < dh)%Z ->
  rg_st C Ar A md s datad nd m0 f fl m ->
  regs_agree (fun x => In x [5; 7; 12; 29; 30]%list) r0 r ->
  getr r 7 = Z_to_bv 64 (psl + 4 * swpl * i + 4) -> getr r 5 = Z_to_bv 64 (pdl + 4 * dwpl * i) -> getr r 12 = Z_to_bv 64 (dh - i) ->
  getr r0 13 = Z_to_bv 64 (4 * swpl) -> getr r0 14 = Z_to_bv 64 (4 * dwpl) -> getr r0 28 = Z_to_bv 64 (if f3 then 1 else 0) ->
  (forall m' r', rg_st C Ar A md s datad nd m0 f fl m' -> regs_agree (fun x => In x [5; 7; 12; 29; 30]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x7bf48 : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x7b218 : word) m al_rom) md) S.
