(* [comment removed for export] *)
Lemma rg3_I_W : forall (n : nat) C Ar A md (s : Z) (S : TSet) (f : frw) (fl : word)
    (datad nd datas ns psrow pdrow nfw : Z) (r0 : bvmap 5 word) m0 m r (j : Z),
  rg_ok C Ar A md s datad nd datas ns -> (1 <= nfw < 2 ^ 26)%Z ->
  (datad <= pdrow)%Z -> (pdrow + 4 * nfw <= datad + nd)%Z -> (datas <= psrow)%Z -> (psrow + 4 * nfw + 4 <= datas + ns)%Z ->
  (Z.of_nat n = nfw - 1 - j)%Z -> (0 <= j < nfw)%Z ->
  rg_st C Ar A md s datad nd m0 f fl m ->
  regs_agree (fun x => In x [22; 23; 24; 31]%list) r0 r ->
  getr r 22 = Z_to_bv 64 (psrow + 4 * j + 4) -> getr r 23 = Z_to_bv 64 (pdrow + 4 * j) -> getr r0 7 = Z_to_bv 64 (pdrow + 4 * nfw) ->
  (forall m' r', rg_st C Ar A md s datad nd m0 f fl m' -> regs_agree (fun x => In x [22; 23; 24; 31]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x7c104 : word) m' al_rom) md) S) ->
