(* [comment removed for export] *)
Lemma rg3_K0 : forall C Ar A md (s : Z) (S : TSet) (f : frw) (fw : bool)
    (datad nd datas ns DX SX DW dy sy dwpl swpl dh psf pdf : Z) (m0 m : word -> option byte) (r : bvmap 5 word),
  rg_ok C Ar A md s datad nd datas ns ->
  (1 <= dh < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z ->
  (0 <= DX < 2 ^ 30)%Z -> (0 <= SX < 2 ^ 30)%Z -> (1 <= DW < 2 ^ 30)%Z -> (0 <= dy * dwpl < 2 ^ 24)%Z -> (0 <= sy * swpl < 2 ^ 24)%Z ->
  (DX mod 32 <> SX mod 32)%Z -> (g_smax DX SX DW <= swpl - 1)%Z -> (g_hang DX <= DW)%Z -> (DX + DW <= 32 * dwpl)%Z -> fw = g_fw DX ->
  (forall c nw i', 0 <= c -> 0 <= nw -> c + nw <= dwpl -> 0 <= i' < dh ->
      datad <= datad + 4 * (dy * dwpl) + 4 * c + 4 * dwpl * i' /\ datad + 4 * (dy * dwpl) + 4 * c + 4 * dwpl * i' + 4 * nw <= datad + nd)%Z ->
  (forall c nw i', 0 <= c -> 0 <= nw -> c + nw <= swpl -> 0 <= i' < dh ->
      datas <= datas + 4 * (sy * swpl) + 4 * c + 4 * swpl * i' /\ datas + 4 * (sy * swpl) + 4 * c + 4 * swpl * i' + 4 * nw <= datas + ns)%Z ->
  psf = (datas + 4 * (sy * swpl) + 4 * (SX / 32))%Z -> pdf = (datad + 4 * (dy * dwpl) + 4 * (DX / 32))%Z ->
  ret_ok (f_ret f) ->
  W C A m md -> POSTM C Ar s m0 m ->
  rlcells m s (f_ret f) (f_v0 f) (f_v1 f) (f_v2 f) (f_v3 f) (f_v4 f) (f_v5 f) (f_v6 f) (f_v7 f) (f_v8 f) (f_v9 f) (f_v10 f) (f_v11 f) ->
  (forall a : word, ~ scratch C s a -> ~ (datad <= u a < datad + nd)%Z -> m a = m0 a) ->
  getr r 2 = Z_to_bv 64 (s - 112) -> getr r 5 = Z_to_bv 64 datad -> getr r 6 = Z_to_bv 64 DW -> getr r 7 = Z_to_bv 64 32 ->
  getr r 12 = Z_to_bv 64 dh -> getr r 13 = Z_to_bv 64 swpl -> getr r 14 = Z_to_bv 64 dwpl -> getr r 16 = Z_to_bv 64 (32 - g_sls DX SX) ->
  getr r 19 = Z_to_bv 64 DX -> getr r 20 = Z_to_bv 64 (DX mod 32) -> getr r 21 = Z_to_bv 64 2 -> getr r 22 = Z_to_bv 64 datas ->
  getr r 23 = Z_to_bv 64 sy -> getr r 26 = Z_to_bv 64 SX -> getr r 27 = Z_to_bv 64 dy -> getr r 28 = Z_to_bv 64 (g_hang DX) ->
  getr r 29 = Z_to_bv 64 (g_hang DX) ->
  (fw = true -> getr r 1 = Z_to_bv 64 psf /\ getr r 8 = Z_to_bv 64 pdf
                /\ getr r 25 = Z_to_bv 64 (if g_f6 DX SX then 1 else 0) /\ getr r 24 = Z_to_bv 64 (if g_f7 SX DW then 1 else 0)) ->
  (forall m' r', W C A m' md -> POSTM C Ar s m0 m' -> (forall a : word, ~ scratch C s a -> ~ (datad <= u a < datad + nd)%Z -> m' a = m0 a) ->
     rg_post f s r r' -> realizes SEGS (mkCfg (mkst r' (f_ret f) m' al_rom) md) S) ->
